    name: { de: "Taimyr-Halbinsel", hu: "Tajmir-félsziget", ro: "Peninsula Taimîr", en: "Taimyr Peninsula"},
    image: "/poi-images/russia-taimyr-peninsula-nature-v2.webp",
    coords: [98.0, 74.0],
